/** ядро_мән 안의 연결형 байт_мән ағым_мән. Ethernet/TCP 패킷 스택이 아닌 루프백 socket қабат_мән. */
public final class ағым_желі {
    static int[] күй_мән = new int[16], порт_мән = new int[16], 짝 = new int[16], бір_рангілі_порт = new int[16], күте_тұрыңыз_мән = new int[16], ақпараттық_жүйелер_шек = new int[16];
    static int[] алдыңғы_камера_мән = new int[16], 수 = new int[16], деректер = new int[16 * 1024];
    static int Келесі_элемент = 50000;
    static int тексеру(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && күй_мән[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int порт_нөмірі) { for (int тұйық_индекс = 0; тұйық_индекс < 16; тұйық_индекс++) if (күй_мән[тұйық_индекс] != 0 && ақпараттық_жүйелер_шек[тұйық_индекс] != 0 && порт_мән[тұйық_индекс] == порт_нөмірі) return true; return false; }
    public static int жасау_енгізу() {
        for (int тұйық_индекс = 0; тұйық_индекс < 16; тұйық_индекс++) if (күй_мән[тұйық_индекс] == 0) { күй_мән[тұйық_индекс] = 1; бір_рангілі_порт[тұйық_индекс] = порт_мән[тұйық_индекс] = алдыңғы_камера_мән[тұйық_индекс] = 수[тұйық_индекс] = күте_тұрыңыз_мән[тұйық_индекс] = ақпараттық_жүйелер_шек[тұйық_индекс] = 0; 짝[тұйық_индекс] = -1; return тұйық_индекс + 40; }
        return -24;
    }
    public static int байланыстыру_қатысушы(int 열린파일번호, int 통신주소, int порт_нөмірі) {
        int тұйық_индекс = тексеру(열린파일번호); if (тұйық_индекс < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (күй_мән[тұйық_индекс] != 1 || порт_нөмірі < 0 || порт_нөмірі > 65535) return -22;
        if (порт_нөмірі == 0) { do { порт_нөмірі = Келесі_элемент++; if (Келесі_элемент > 65535) Келесі_элемент = 50000; } while (사용중(порт_нөмірі)); }
        if (사용중(порт_нөмірі)) return -98; порт_мән[тұйық_индекс] = порт_нөмірі; ақпараттық_жүйелер_шек[тұйық_индекс] = 1; күй_мән[тұйық_индекс] = 2; return 0;
    }
    public static int деректердің_берілуін_күту_қатысушы(int 열린파일번호, int 연결대기한도) { int тұйық_индекс = тексеру(열린파일번호); if (тұйық_индекс < 0) return -9; if (күй_мән[тұйық_индекс] != 2 || 연결대기한도 < 1) return -22; күй_мән[тұйық_индекс] = 3; return 0; }
    public static int Байланысу(int 열린파일번호, int 통신주소, int порт_нөмірі) {
        int тұйық_индекс = тексеру(열린파일번호); if (тұйық_индекс < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (порт_нөмірі < 1 || порт_нөмірі > 65535 || күй_мән[тұйық_индекс] > 2) return -22;
        int 수신쪽 = -1; for (int ішкі_лауазым = 0; ішкі_лауазым < 16; ішкі_лауазым++) if (күй_мән[ішкі_лауазым] == 3 && порт_мән[ішкі_лауазым] == порт_нөмірі) 수신쪽 = ішкі_лауазым;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int ішкі_лауазым = 0; ішкі_лауазым < 16; ішкі_лауазым++) if (күте_тұрыңыз_мән[ішкі_лауазым] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (күй_мән[тұйық_индекс] == 1) { int 처리값 = байланыстыру_қатысушы(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = жасау_енгізу(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        күй_мән[тұйық_индекс] = күй_мән[다른번호] = 4; 짝[тұйық_индекс] = 다른번호; 짝[다른번호] = тұйық_индекс; порт_мән[다른번호] = порт_нөмірі; бір_рангілі_порт[тұйық_индекс] = порт_нөмірі; бір_рангілі_порт[다른번호] = порт_мән[тұйық_индекс]; күте_тұрыңыз_мән[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int қабылдау_қосылым(int 열린파일번호) { int тұйық_индекс = тексеру(열린파일번호); if (тұйық_индекс < 0) return -9; if (күй_мән[тұйық_индекс] != 3) return -22; for (int ішкі_лауазым = 0; ішкі_лауазым < 16; ішкі_лауазым++) if (күй_мән[ішкі_лауазым] != 0 && күте_тұрыңыз_мән[ішкі_лауазым] == тұйық_индекс + 1) { күте_тұрыңыз_мән[ішкі_лауазым] = 0; return ішкі_лауазым + 40; } return -11; }
    public static int Жазу(int 열린파일번호, int 항목수) {
        int тұйық_индекс = тексеру(열린파일번호); if (тұйық_индекс < 0) return -9; if (күй_мән[тұйық_индекс] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int ішкі_лауазым = 짝[тұйық_индекс]; if (ішкі_лауазым < 0) return -32; int 총수 = 1024 - 수[ішкі_лауазым]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int Салыстыру_лауазым = 0; Салыстыру_лауазым < 총수; Салыстыру_лауазым++) деректер[ішкі_лауазым * 1024 + (алдыңғы_камера_мән[ішкі_лауазым] + 수[ішкі_лауазым] + Салыстыру_лауазым) % 1024] = 되돌림망.Алға_мән[Салыстыру_лауазым]; 수[ішкі_лауазым] += 총수; return 총수;
    }
    public static int Оқу(int 열린파일번호, int 항목수) {
        int тұйық_индекс = тексеру(열린파일번호); if (тұйық_индекс < 0) return -9; if (күй_мән[тұйық_индекс] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[тұйық_индекс] == 0) return 짝[тұйық_индекс] < 0 ? 0 : -11; if (항목수 > 수[тұйық_индекс]) 항목수 = 수[тұйық_индекс];
        for (int Салыстыру_лауазым = 0; Салыстыру_лауазым < 항목수; Салыстыру_лауазым++) 되돌림망.Алға_мән[Салыстыру_лауазым] = деректер[тұйық_индекс * 1024 + (алдыңғы_камера_мән[тұйық_индекс] + Салыстыру_лауазым) % 1024]; алдыңғы_камера_мән[тұйық_индекс] = (алдыңғы_камера_мән[тұйық_индекс] + 항목수) % 1024; 수[тұйық_индекс] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int тұйық_индекс = тексеру(열린파일번호); return тұйық_индекс < 0 ? -9 : порт_мән[тұйық_индекс]; }
    public static int 상대창구읽기(int 열린파일번호) { int тұйық_индекс = тексеру(열린파일번호); return тұйық_индекс < 0 ? -9 : бір_рангілі_порт[тұйық_индекс]; }
    public static int Жабу(int 열린파일번호) {
        int тұйық_индекс = тексеру(열린파일번호); if (тұйық_индекс < 0) return -9;
        if (күй_мән[тұйық_индекс] == 3) for (int ішкі_лауазым = 0; ішкі_лауазым < 16; ішкі_лауазым++) if (күте_тұрыңыз_мән[ішкі_лауазым] == тұйық_индекс + 1) { if (짝[ішкі_лауазым] >= 0) 짝[짝[ішкі_лауазым]] = -1; күй_мән[ішкі_лауазым] = күте_тұрыңыз_мән[ішкі_лауазым] = ақпараттық_жүйелер_шек[ішкі_лауазым] = 0; }
        if (짝[тұйық_индекс] >= 0) 짝[짝[тұйық_индекс]] = -1; күй_мән[тұйық_индекс] = ақпараттық_жүйелер_шек[тұйық_индекс] = 수[тұйық_индекс] = күте_тұрыңыз_мән[тұйық_индекс] = 0; return 0;
    }
}
